//! Project-owned demo cars.
//!
//! The RCP pack in `content/demo/cars` (generated by `racer-cargen`) is
//! embedded at build time. Each car body is a flat-shaded mesh whose per-vertex
//! UV addresses a palette texture; a paint option recolours palette entries,
//! so every car is available in several colours. Wheels are instanced from the
//! car's shared wheel mesh and baked into the body for the renderer.

use racer_pack_schema::car::{PaintScheme, PaletteEntry};
use racer_pack_schema::vehicle::VehicleDef;
use racer_pack_schema::{BufferBytes, Car, Pack};
use racer_render::{IndexedMesh, Material, MeshVertex, UvWrap, Vec3, VehicleMesh};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::sync::OnceLock;

macro_rules! embed_text {
    ($files:ident, $($path:literal),+ $(,)?) => {
        $($files.insert(
            $path.to_string(),
            include_bytes!(concat!("../../../content/demo/cars/", $path)).to_vec(),
        );)+
    };
}

fn embedded_files() -> BTreeMap<String, Vec<u8>> {
    let mut files = BTreeMap::new();
    embed_text!(
        files,
        "pack.json",
        "cars/quill-coupe.json",
        "cars/brisk-roadster.json",
        "cars/tumble-rally.json",
        "cars/shard-gt.json",
        "vehicles/quill-coupe.json",
        "vehicles/brisk-roadster.json",
        "vehicles/tumble-rally.json",
        "vehicles/shard-gt.json",
        "buffers/quill-coupe.bin",
        "buffers/brisk-roadster.bin",
        "buffers/tumble-rally.bin",
        "buffers/shard-gt.bin",
    );
    files
}

/// One selectable paint scheme of a car.
#[derive(Clone, Debug, PartialEq)]
pub struct PaintInfo {
    /// Stable identifier, for example `signal-red`.
    pub id: String,
    /// Display colour of the body paint, 8-bit sRGB.
    pub body: [u8; 3],
}

/// Catalogue entry of one demo car.
#[derive(Clone, Debug)]
pub struct ProjectCar {
    pub id: String,
    pub name: String,
    pub vehicle: VehicleDef,
    pub paints: Vec<PaintInfo>,
    car: Car,
}

/// All demo cars with their buffers.
pub struct ProjectCars {
    cars: Vec<ProjectCar>,
    buffers: BufferBytes,
}

/// The embedded, validated demo-car catalogue.
pub fn project_cars() -> &'static ProjectCars {
    static CARS: OnceLock<ProjectCars> = OnceLock::new();
    CARS.get_or_init(|| {
        let pack = Pack::from_files(&embedded_files()).expect("embedded demo cars parse");
        pack.validate().expect("embedded demo cars validate");
        let cars = pack
            .cars
            .iter()
            .map(|car| {
                let vehicle = pack
                    .vehicles
                    .iter()
                    .find(|v| v.car.as_deref() == Some(car.id.as_str()))
                    .expect("every demo car has a vehicle")
                    .clone();
                let paints = car
                    .paint
                    .as_ref()
                    .map(|p| {
                        p.options
                            .iter()
                            .map(|o| PaintInfo {
                                id: o.name.clone(),
                                body: {
                                    let c = apply_option(&p.base_palette, &o.scheme)[0];
                                    [c[0], c[1], c[2]]
                                },
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                ProjectCar {
                    id: car.id.clone(),
                    name: car.name.clone(),
                    vehicle,
                    paints,
                    car: car.clone(),
                }
            })
            .collect();
        ProjectCars {
            cars,
            buffers: pack.buffers,
        }
    })
}

fn apply_option(base: &[[u8; 4]], scheme: &PaintScheme) -> Vec<[u8; 4]> {
    let mut palette = base.to_vec();
    match scheme {
        PaintScheme::Recolour { entries } => {
            for PaletteEntry { index, color } in entries {
                palette[*index as usize] = *color;
            }
        }
        PaintScheme::FullPalette { colors } => palette = colors.clone(),
    }
    palette
}

impl ProjectCars {
    pub fn cars(&self) -> &[ProjectCar] {
        &self.cars
    }

    pub fn find(&self, id: &str) -> Option<&ProjectCar> {
        self.cars.iter().find(|c| c.id == id)
    }

    /// Index of the car with `id` in [`Self::cars`].
    pub fn index_of(&self, id: &str) -> Option<usize> {
        self.cars.iter().position(|c| c.id == id)
    }

    /// Indices of a car and paint scheme by their identifiers.
    pub fn lookup(&self, car_id: &str, paint_id: &str) -> Option<(usize, usize)> {
        let car = self.index_of(car_id)?;
        let paint = self.cars[car]
            .paints
            .iter()
            .position(|p| p.id == paint_id)?;
        Some((car, paint))
    }

    /// Cars and paints of a race field: the player first, then up to seven
    /// opponents, all different from each other (cars cycle, paints step by a
    /// number coprime to the paint count). At most eight entries, the
    /// renderer's profile limit.
    pub fn roster(&self, player: (usize, usize), opponents: usize) -> Vec<(usize, usize)> {
        let cars = self.cars.len();
        let mut field = vec![player];
        for k in 0..opponents.min(7) {
            let car = (player.0 + 1 + k) % cars;
            let paints = self.cars[car].paints.len();
            field.push((car, (player.1 + 2 + 3 * k) % paints));
        }
        field
    }

    /// Car and paint of computer opponent `k` (0-based) in a field led by
    /// `base`: the same pairing [`Self::roster`] uses, so every machine that
    /// knows the base and the opponent index derives the same car.
    pub fn opponent_pick(&self, base: (usize, usize), k: usize) -> (usize, usize) {
        let k = k.min(6);
        self.roster(base, k + 1)[k + 1]
    }

    /// Render profile identifier of a car in a paint, valid for the
    /// renderer's `a-z 0-9 -` profile format.
    pub fn profile_id(&self, car: usize, paint: usize) -> String {
        format!(
            "pc-{}-{}",
            self.cars[car].id, self.cars[car].paints[paint].id
        )
    }

    /// Lowercase SHA-256 binding a profile to its exact geometry and colours.
    pub fn profile_fingerprint(&self, car: usize, paint: usize) -> Result<String, String> {
        let mesh = self.vehicle_mesh(car, paint)?;
        let mut h = Sha256::new();
        h.update(self.profile_id(car, paint).as_bytes());
        for v in &mesh.mesh.vertices {
            for f in [
                v.position.x,
                v.position.y,
                v.position.z,
                v.normal.x,
                v.normal.y,
                v.normal.z,
            ] {
                h.update(f.to_le_bytes());
            }
            h.update(v.material.to_le_bytes());
        }
        for m in &mesh.materials {
            for f in m.tint {
                h.update(f.to_le_bytes());
            }
        }
        Ok(h.finalize().iter().map(|b| format!("{b:02x}")).collect())
    }

    /// Body plus wheels of a car in a paint, in renderer space (forward +X,
    /// left +Y, up +Z, wheels on z = 0). Material `i` is palette entry `i`.
    pub fn vehicle_mesh(&self, car: usize, paint: usize) -> Result<VehicleMesh, String> {
        let entry = self.cars.get(car).ok_or("unknown demo car")?;
        let doc = &entry.car;
        let set = doc.paint.as_ref().ok_or("demo car has no paint set")?;
        let option = set.options.get(paint).ok_or("unknown paint scheme")?;
        let palette = apply_option(&set.base_palette, &option.scheme);

        let mut mesh = IndexedMesh::default();
        let body = &doc.lods[0].mesh;
        self.append(&mut mesh, doc, body, &|p| p, &|n| n)?;
        if let Some(wheel) = &doc.wheel_mesh {
            for anchor in &doc.wheels {
                let [ax, ay, az] = anchor.position;
                let flip = ax < 0.0;
                let place = move |p: [f32; 3]| {
                    let (x, z) = if flip { (-p[0], -p[2]) } else { (p[0], p[2]) };
                    [x + ax, p[1] + ay, z + az]
                };
                let turn = move |n: [f32; 3]| if flip { [-n[0], n[1], -n[2]] } else { n };
                self.append(&mut mesh, doc, wheel, &place, &turn)?;
            }
        }
        let materials = palette
            .iter()
            .enumerate()
            .map(|(i, c)| {
                Material::whole_layer(
                    format!("{}-{i}", entry.id),
                    [
                        f32::from(c[0]) / 255.0,
                        f32::from(c[1]) / 255.0,
                        f32::from(c[2]) / 255.0,
                        1.0,
                    ],
                    0,
                    UvWrap::Clamp,
                )
            })
            .collect();
        Ok(VehicleMesh { mesh, materials })
    }

    fn append(
        &self,
        out: &mut IndexedMesh,
        doc: &Car,
        mesh: &racer_pack_schema::common::Mesh,
        place: &dyn Fn([f32; 3]) -> [f32; 3],
        turn: &dyn Fn([f32; 3]) -> [f32; 3],
    ) -> Result<(), String> {
        let positions = doc.data.read_f32(mesh.positions, &self.buffers)?;
        let normals = doc.data.read_f32(
            mesh.normals.ok_or("demo car mesh has no normals")?,
            &self.buffers,
        )?;
        let uvs = doc
            .data
            .read_f32(mesh.uv.ok_or("demo car mesh has no uv")?, &self.buffers)?;
        let indices = doc.data.read_u32(mesh.indices, &self.buffers)?;
        let base = out.vertices.len() as u32;
        // RCP frame (+Y up, -Z forward) to renderer frame (+Z up, +X forward).
        let to_render = |v: [f32; 3]| Vec3::new(-v[2], -v[0], v[1]);
        for ((p, n), uv) in positions
            .chunks_exact(3)
            .zip(normals.chunks_exact(3))
            .zip(uvs.chunks_exact(2))
        {
            let material = ((uv[0] * 8.0).floor().max(0.0) as u32).min(7);
            out.vertices.push(MeshVertex {
                position: to_render(place([p[0], p[1], p[2]])),
                normal: to_render(turn([n[0], n[1], n[2]])),
                uv: [0.5, 0.5],
                material,
            });
        }
        out.indices.extend(indices.iter().map(|i| base + i));
        Ok(())
    }

    /// Catalogue for the browser: id, name and paint list of every car.
    pub fn catalog_json(&self) -> String {
        let cars: Vec<serde_json::Value> = self
            .cars
            .iter()
            .map(|c| {
                serde_json::json!({
                    "id": c.id,
                    "name": c.name,
                    "engine_sound": c.vehicle.engine_sound,
                    "paints": c.paints.iter().map(|p| serde_json::json!({
                        "id": p.id,
                        "body": format!("#{:02x}{:02x}{:02x}", p.body[0], p.body[1], p.body[2]),
                    })).collect::<Vec<_>>(),
                })
            })
            .collect();
        serde_json::json!({ "cars": cars }).to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_catalogue_has_four_cars_with_eight_paints() {
        let cars = project_cars();
        assert_eq!(cars.cars().len(), 4);
        for c in cars.cars() {
            assert_eq!(c.paints.len(), 8, "{}", c.id);
            assert!(c.vehicle.arcade.is_some());
        }
    }

    #[test]
    fn meshes_stand_on_the_ground_face_forward_and_are_distinct() {
        let cars = project_cars();
        let mut lengths = Vec::new();
        let mut bounds = Vec::new();
        for i in 0..4 {
            let m = cars.vehicle_mesh(i, 0).unwrap();
            assert!(m.mesh.is_well_formed());
            assert_eq!(m.materials.len(), 8);
            let (mut lo, mut hi) = (
                Vec3::new(f32::MAX, f32::MAX, f32::MAX),
                Vec3::new(f32::MIN, f32::MIN, f32::MIN),
            );
            for v in &m.mesh.vertices {
                lo = Vec3::new(
                    lo.x.min(v.position.x),
                    lo.y.min(v.position.y),
                    lo.z.min(v.position.z),
                );
                hi = Vec3::new(
                    hi.x.max(v.position.x),
                    hi.y.max(v.position.y),
                    hi.z.max(v.position.z),
                );
                assert!(v.material < 8);
            }
            assert!(lo.z.abs() < 1e-3, "wheels rest on z = 0: {}", lo.z);
            assert!(hi.x - lo.x > 3.5 && hi.x - lo.x < 5.0, "length along +X");
            assert!(hi.y - lo.y > 1.6 && hi.y - lo.y < 2.2, "width along Y");
            assert!(hi.z < 1.9);
            lengths.push(hi.x - lo.x);
            bounds.push(format!("{:.2}/{:.2}/{:.2}", hi.x - lo.x, hi.y - lo.y, hi.z));
        }
        bounds.sort();
        bounds.dedup();
        assert_eq!(bounds.len(), 4);
    }

    #[test]
    fn wheels_are_baked_at_all_four_anchors() {
        let cars = project_cars();
        let doc = &cars.cars()[0].car;
        let body_only = {
            let mut m = IndexedMesh::default();
            cars.append(&mut m, doc, &doc.lods[0].mesh, &|p| p, &|n| n)
                .unwrap();
            m.vertices.len()
        };
        let full = cars.vehicle_mesh(0, 0).unwrap().mesh.vertices.len();
        let wheel =
            doc.data.accessors[doc.wheel_mesh.as_ref().unwrap().positions as usize].count as usize;
        assert_eq!(full, body_only + 4 * wheel);
    }

    #[test]
    fn paint_changes_only_the_body_materials() {
        let cars = project_cars();
        let red = cars.vehicle_mesh(0, 0).unwrap();
        let blue = cars.vehicle_mesh(0, 1).unwrap();
        assert_eq!(red.mesh, blue.mesh);
        assert_ne!(red.materials[0].tint, blue.materials[0].tint);
        assert_ne!(red.materials[1].tint, blue.materials[1].tint);
        for i in 2..8 {
            assert_eq!(red.materials[i].tint, blue.materials[i].tint);
        }
        assert_ne!(
            cars.profile_fingerprint(0, 0).unwrap(),
            cars.profile_fingerprint(0, 1).unwrap()
        );
    }

    #[test]
    fn rosters_never_repeat_a_car_and_paint_pair() {
        let cars = project_cars();
        for car in 0..4 {
            for paint in 0..8 {
                let field = cars.roster((car, paint), 7);
                assert_eq!(field.len(), 8);
                assert_eq!(field[0], (car, paint));
                let unique: std::collections::BTreeSet<_> = field.iter().collect();
                assert_eq!(unique.len(), 8, "{field:?}");
                // Opponents drive more than one kind of car.
                let kinds: std::collections::BTreeSet<_> = field.iter().map(|f| f.0).collect();
                assert_eq!(kinds.len(), 4);
            }
        }
        assert_eq!(cars.roster((1, 2), 0), vec![(1, 2)]);
        assert_eq!(cars.roster((1, 2), 3).len(), 4);
        assert_eq!(cars.lookup("shard-gt", "plum"), Some((3, 7)));
        assert_eq!(cars.lookup("nope", "plum"), None);
    }

    #[test]
    fn opponent_picks_match_the_roster_for_every_base() {
        let cars = project_cars();
        for car in 0..4 {
            for paint in 0..8 {
                let field = cars.roster((car, paint), 7);
                for k in 0..7 {
                    assert_eq!(cars.opponent_pick((car, paint), k), field[1 + k]);
                }
                // an out-of-range index stays inside the catalogue
                assert_eq!(cars.opponent_pick((car, paint), 40), field[7]);
            }
        }
    }

    #[test]
    fn profile_ids_satisfy_the_renderer_format() {
        let cars = project_cars();
        for car in 0..4 {
            for paint in 0..8 {
                let id = cars.profile_id(car, paint);
                assert!(id.len() <= 64);
                assert!(
                    id.bytes()
                        .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
                );
                let fp = cars.profile_fingerprint(car, paint).unwrap();
                assert_eq!(fp.len(), 64);
            }
        }
    }
}
